export const body = "<h2>Let's answer that pesky question</h2>\n\n<p>An integral part of art production is iterating. But the ambiguous nature of art makes it hard to iterate sometimes. Artists could usually tell if something is off about their work. \"<strong>What's wrong with my render?</strong>\" they might ask. But there are times when they couldn't tell where the problem is. Their viewers agreed with the sentiment, but couldn't provide any answer, either.</p>\n\n<p>Here, we'll learn a theory to answer that pesky question. Whether your render is a creature, a piece of nature, or a product of future technology, this theory is applicable across the board. It is known as big-medium-small.</p>\n\n<p><a class=\"source-figure\" href=\"assets/concept-inline/290190cf50544813eb2f.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/290190cf50544813eb2f.webp\" width=\"1150\" height=\"501\" style=\"--source-width:566px\" alt=\"Illustration 1\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<p><a class=\"source-figure\" href=\"assets/concept-inline/509150a70bf6aaba0659.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/509150a70bf6aaba0659.webp\" width=\"1150\" height=\"500\" style=\"--source-width:566px\" alt=\"Illustration 2\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<p><a class=\"source-figure\" href=\"assets/concept-inline/4c37b9ca9da8bba9f545.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/4c37b9ca9da8bba9f545.webp\" width=\"1150\" height=\"384\" style=\"--source-width:566px\" alt=\"Illustration 3\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<p><a class=\"source-figure\" href=\"assets/concept-inline/81570bde8dd97a4aaa6d.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/81570bde8dd97a4aaa6d.webp\" width=\"1150\" height=\"383\" style=\"--source-width:566px\" alt=\"Illustration 4\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<h2>So, what is it?</h2>\n\n<p>If your image has a nice distribution of big, medium and small shapes, the resulting image will tend to be more pleasing to the eye.</p>\n\n<p>So, there are two core pillars to this theory:1</p>\n\n<p>A good design contains shapes of 3 sizes: big, medium and small2</p>\n\n<p>The distribution of these 3 shape categories must be logical</p>\n\n<p>With that in mind, we'll learn how to tailor our shapes and how to sprinkle them in a visually appealing manner.</p>\n\n<h2>Shapes and sizes</h2>\n\n<p>Starting with size, it helps to know that sometimes people refer to the 3 categories as <em>primary</em>,<em> secondary</em>, and,<em> tertiary</em> shapes too. Primary is big, secondary medium, tertiary small.</p>\n\n<p>In terms of function, these 3 shape categories go as follows.1</p>\n\n<p><strong>Big shape</strong>: shows the general silhouette of your render → should be clear when seen from afar2</p>\n\n<p><strong>Medium shapes</strong>: sit on top of or make up the big shape to enrich it3</p>\n\n<p><strong>Small shapes</strong>: provide granular details that add visual interest to your render</p>\n\n<p>One key point to remember is you should have variations within each size category. If each category relies on just one shape, the result will be monotonous. But choosing and varying the sizes of your shapes can be quite a headache. Here, we share two formulas that you can try, but feel free to put your own spin on them.</p>\n\n<div class=\"source-table\"><table><tbody><tr><td><p><a class=\"source-figure\" href=\"assets/concept-inline/47a5ecbc2b3fcc4d33d7.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/47a5ecbc2b3fcc4d33d7.webp\" width=\"294\" height=\"190\" style=\"--source-width:261px\" alt=\"Illustration 5\" loading=\"lazy\" decoding=\"async\"></a></p></td><td><p><a class=\"source-figure\" href=\"assets/concept-inline/5a6afdd34881591ed888.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/5a6afdd34881591ed888.webp\" width=\"294\" height=\"197\" style=\"--source-width:294px\" alt=\"Illustration 6\" loading=\"lazy\" decoding=\"async\"></a></p></td></tr><tr><td><p><strong>Big</strong> (primary)</p></td><td><p><strong>Medium</strong> (secondary)</p></td></tr><tr><td><p><a class=\"source-figure\" href=\"assets/concept-inline/eadd47f1bb70d19d0a42.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/eadd47f1bb70d19d0a42.webp\" width=\"294\" height=\"196\" style=\"--source-width:261px\" alt=\"Illustration 7\" loading=\"lazy\" decoding=\"async\"></a></p></td><td><p><a class=\"source-figure\" href=\"assets/concept-inline/a59ba43b59fc6a9601ce.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/a59ba43b59fc6a9601ce.webp\" width=\"289\" height=\"197\" style=\"--source-width:289px\" alt=\"Illustration 8\" loading=\"lazy\" decoding=\"async\"></a></p></td></tr><tr><td><p><strong>Small</strong> (tertiary)</p></td><td><p><strong>Big-medium-small</strong></p></td></tr></tbody></table></div>\n\n<p><a class=\"source-figure\" href=\"assets/concept-inline/0314e68a599ab7f094c8.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/0314e68a599ab7f094c8.webp\" width=\"627\" height=\"435\" style=\"--source-width:566px\" alt=\"Illustration 9\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<p><a class=\"source-figure\" href=\"assets/concept-inline/d06d3136e9e25cd93ceb.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/d06d3136e9e25cd93ceb.webp\" width=\"628\" height=\"458\" style=\"--source-width:566px\" alt=\"Illustration 10\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<h3>The 70/30 rule</h3>\n\n<p>The first formula is the 70/30 rule. If you have a primary shape, and you want to break it up into 2 secondary shapes, it's better to break it up into one shape that is 70% of the size, and one shape that's 30% of the size, then two secondary shapes that are both 50% of the original size.</p>\n\n<p>The same works for tertiary shapes. If you break up a secondary shape into multiple tertiary shapes, consider breaking it up into a bunch of tertiary shapes that are 30% the size of the secondary shapes.</p>\n\n<h3>The 1:5 or 1:10 rule</h3>\n\n<p>The second formula is the 1:5 or 1:10 rule. Essentially, it means:</p>\n\n<ul><li>Your medium shapes should be 5 to 10 times smaller than your big shape</li><li>Likewise, your small shapes should be 5 to 10 times smaller than the medium ones</li></ul>\n\n<p>Though this is not the right ratio for all renders, it's still a solid starting point for you to iterate on down the line.</p>\n\n<p><a class=\"source-figure\" href=\"assets/concept-inline/1510738221b4111d5af6.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/1510738221b4111d5af6.webp\" width=\"1150\" height=\"481\" style=\"--source-width:566px\" alt=\"Illustration 11\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<p><a class=\"source-figure\" href=\"assets/concept-inline/201f94e3de45281078f7.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/201f94e3de45281078f7.webp\" width=\"1150\" height=\"468\" style=\"--source-width:566px\" alt=\"Illustration 12\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<p><a class=\"source-figure\" href=\"assets/concept-inline/1d38764c6b8b6877f917.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/1d38764c6b8b6877f917.webp\" width=\"1150\" height=\"353\" style=\"--source-width:566px\" alt=\"Illustration 13\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<p><a class=\"source-figure\" href=\"assets/concept-inline/941efd6aab50c149b3cd.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/941efd6aab50c149b3cd.webp\" width=\"1150\" height=\"335\" style=\"--source-width:566px\" alt=\"Illustration 14\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<h2>Shape distribution</h2>\n\n<p>Now that you got all 3 categories in place, you might be wondering: \"So, where should the go?\" An attractive render, whether it's a character or an environment, has clearly defined areas of rest and areas of detail. Therefore, placing your shapes evenly like the rock in the top picture is ill advice. However, that doesn't mean you can't clump your shapes. Let's dig deeper.</p>\n\n<p><strong>EXAMPLE</strong><strong>: shape distribution</strong></p>\n\n<p><a class=\"source-figure\" href=\"assets/concept-inline/61b0e51119a8aaa7466b.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/61b0e51119a8aaa7466b.webp\" width=\"1150\" height=\"494\" style=\"--source-width:566px\" alt=\"Illustration 15\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<p><a class=\"source-figure\" href=\"assets/concept-inline/4cd66cbb4d6c0dfc0079.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/4cd66cbb4d6c0dfc0079.webp\" width=\"1150\" height=\"288\" style=\"--source-width:566px\" alt=\"Illustration 16\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<h3>Areas of rest &amp; areas of detail</h3>\n\n<p>You also need to offset details with <strong>negative space</strong>. If everything calls for attention, nothing will get the attention. By having empty space, you can emphasize the finer details in your designs. This opposite helmet has plenty of negative space, which allows small details such as screws, welding lines, and vent holes to stand out more.</p>\n\n<p>Meanwhile, Dinobot (from <em>Transformers 5</em>) has too many small shapes clustered at the head section, while the body contains very few of them.</p>\n\n<p><a class=\"source-figure\" href=\"assets/concept-inline/b3c09a95907658cda64d.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/b3c09a95907658cda64d.webp\" width=\"1150\" height=\"543\" style=\"--source-width:566px\" alt=\"Illustration 17\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<p><a class=\"source-figure\" href=\"assets/concept-inline/8347e2161ae9b7a57aca.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/8347e2161ae9b7a57aca.webp\" width=\"1150\" height=\"454\" style=\"--source-width:566px\" alt=\"Illustration 18\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<p><strong>EXAMPLE</strong><strong>: areas of rest &amp; areas of detail</strong></p>\n\n<p><a class=\"source-figure\" href=\"assets/concept-inline/8c4ed56ee5e92aae3f29.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/8c4ed56ee5e92aae3f29.webp\" width=\"1150\" height=\"314\" style=\"--source-width:566px\" alt=\"Illustration 19\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<p><a class=\"source-figure\" href=\"assets/concept-inline/4ef491297db688c78dbf.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/4ef491297db688c78dbf.webp\" width=\"1150\" height=\"430\" style=\"--source-width:566px\" alt=\"Illustration 20\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<p><a class=\"source-figure\" href=\"assets/concept-inline/e167bea633120d386859.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/e167bea633120d386859.webp\" width=\"1150\" height=\"469\" style=\"--source-width:566px\" alt=\"Illustration 21\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<p><a class=\"source-figure\" href=\"assets/concept-inline/ecb5430ff682509b6523.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/ecb5430ff682509b6523.webp\" width=\"1150\" height=\"521\" style=\"--source-width:566px\" alt=\"Illustration 22\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<h3>Clumping</h3>\n\n<p>The human brain processes information in chunks, so when you group details together, they become more readable and attractive.</p>\n\n<p>This pattern of detail distribution is very prevalent in nature. Maybe that's why it looks so pleasing to our eyes. Knowing this theory not only helps you create visually appealing art, but also visually irritating designs. You just need to distribute your shapes evenly without clumping.</p>\n\n<p><strong>EXAMPLE</strong><strong>: clumping shapes</strong></p>\n\n<p><strong><a class=\"source-figure\" href=\"assets/concept-inline/3ecaf7d10000c413f816.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/3ecaf7d10000c413f816.webp\" width=\"1150\" height=\"349\" style=\"--source-width:566px\" alt=\"Illustration 23\" loading=\"lazy\" decoding=\"async\"></a></strong></p>\n\n<p><strong><a class=\"source-figure\" href=\"assets/concept-inline/5bace9b5b4fbfdf24851.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/5bace9b5b4fbfdf24851.webp\" width=\"1150\" height=\"726\" style=\"--source-width:566px\" alt=\"Illustration 24\" loading=\"lazy\" decoding=\"async\"></a></strong></p>\n\n<p><strong><a class=\"source-figure\" href=\"assets/concept-inline/961f368063df70853973.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/961f368063df70853973.webp\" width=\"1150\" height=\"720\" style=\"--source-width:566px\" alt=\"Illustration 25\" loading=\"lazy\" decoding=\"async\"></a></strong></p>\n\n<h2>A workflow example</h2>\n\n<p>Sometimes, you need to do more than 3 passes for your render. In this case, there are 4 passes in total.1</p>\n\n<p><strong>First pass</strong>: largest shapes2</p>\n\n<p><strong>Second pass</strong>: supporting shapes that make up the big shapes3</p>\n\n<p><strong>Third pass</strong>: small shapes that add detail4</p>\n\n<p><strong>Fourth pass</strong>: super tiny shapes that add further detail</p>\n\n<p><a class=\"source-figure\" href=\"assets/concept-inline/51d167615a7f240fa6af.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/51d167615a7f240fa6af.webp\" width=\"1150\" height=\"625\" style=\"--source-width:566px\" alt=\"Illustration 26\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<p><a class=\"source-figure\" href=\"assets/concept-inline/0d5221c33d0004d18e47.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/0d5221c33d0004d18e47.webp\" width=\"1064\" height=\"595\" style=\"--source-width:566px\" alt=\"Illustration 27\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<p><a class=\"source-figure\" href=\"assets/concept-inline/3f409fa07e9dc12fadb8.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/3f409fa07e9dc12fadb8.webp\" width=\"1150\" height=\"542\" style=\"--source-width:566px\" alt=\"Illustration 28\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<p><a class=\"source-figure\" href=\"assets/concept-inline/a0362612466e3584117b.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/a0362612466e3584117b.webp\" width=\"1150\" height=\"519\" style=\"--source-width:566px\" alt=\"Illustration 29\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<h2>Answering that question</h2>\n\n<p>From now on, whenever you find something wrong in your designs, take a step back and check whether you:</p>\n\n<ul><li>Have large, medium, and small shapes</li><li>Have variety to the size of shapes in each of the three categories</li><li>Make sure the shapes are placed around the image in interesting patterns — not evenly distributed</li><li>Make sure there are areas of details and areas of rest</li></ul>\n\n<p>As said earlier, these are just guidelines that you can choose to follow or not. But you should be aware of the effect your renders have on the viewer when you decide against these guidelines.</p>\n\n<p>This theory isn't limited to individual pieces of art, however. The distribution and variation of shapes can come in handy for level artists as well.</p>\n\n<p><a class=\"source-figure\" href=\"assets/concept-inline/76c8506bee06aa2d31c8.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/76c8506bee06aa2d31c8.webp\" width=\"1150\" height=\"681\" style=\"--source-width:566px\" alt=\"Illustration 30\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<p><a class=\"source-figure\" href=\"assets/concept-inline/a67f2a863d79aca8495f.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/concept-inline/a67f2a863d79aca8495f.webp\" width=\"1150\" height=\"627\" style=\"--source-width:566px\" alt=\"Illustration 31\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n";
export const images = ["assets/concept-inline/0314e68a599ab7f094c8.webp", "assets/concept-inline/0d5221c33d0004d18e47.webp", "assets/concept-inline/1510738221b4111d5af6.webp", "assets/concept-inline/1d38764c6b8b6877f917.webp", "assets/concept-inline/201f94e3de45281078f7.webp", "assets/concept-inline/290190cf50544813eb2f.webp", "assets/concept-inline/3ecaf7d10000c413f816.webp", "assets/concept-inline/3f409fa07e9dc12fadb8.webp", "assets/concept-inline/47a5ecbc2b3fcc4d33d7.webp", "assets/concept-inline/4c37b9ca9da8bba9f545.webp", "assets/concept-inline/4cd66cbb4d6c0dfc0079.webp", "assets/concept-inline/4ef491297db688c78dbf.webp", "assets/concept-inline/509150a70bf6aaba0659.webp", "assets/concept-inline/51d167615a7f240fa6af.webp", "assets/concept-inline/5a6afdd34881591ed888.webp", "assets/concept-inline/5bace9b5b4fbfdf24851.webp", "assets/concept-inline/61b0e51119a8aaa7466b.webp", "assets/concept-inline/76c8506bee06aa2d31c8.webp", "assets/concept-inline/81570bde8dd97a4aaa6d.webp", "assets/concept-inline/8347e2161ae9b7a57aca.webp", "assets/concept-inline/8c4ed56ee5e92aae3f29.webp", "assets/concept-inline/941efd6aab50c149b3cd.webp", "assets/concept-inline/961f368063df70853973.webp", "assets/concept-inline/a0362612466e3584117b.webp", "assets/concept-inline/a59ba43b59fc6a9601ce.webp", "assets/concept-inline/a67f2a863d79aca8495f.webp", "assets/concept-inline/b3c09a95907658cda64d.webp", "assets/concept-inline/d06d3136e9e25cd93ceb.webp", "assets/concept-inline/e167bea633120d386859.webp", "assets/concept-inline/eadd47f1bb70d19d0a42.webp", "assets/concept-inline/ecb5430ff682509b6523.webp"];
